<div class="page-heading"><div><span class="section-kicker">PERMITTED RECORD</span><h1><?= e($person['full_name']) ?></h1><p>Access follows your current jurisdiction. Any permitted actions appear below.</p></div><a class="btn btn-light" href="<?= e(url('voters')) ?>">Back to records</a></div><section class="card card-body"><div class="row"><div class="col-md-3"><img class="img-fluid rounded" src="<?= e(url('voter_photo',['id'=>$person['id']])) ?>" alt="Photo if recorded" loading="lazy"></div><div class="col-md-9"><dl class="row"><?php foreach(['voter_id'=>'Voter ID','gender'=>'Gender','region'=>'Region','constituency'=>'Constituency','branch'=>'Electoral area','station'=>'Polling station','station_code'=>'Station ID'] as $key=>$label): ?><dt class="col-sm-4"><?= e($label) ?></dt><dd class="col-sm-8"><?= e($person[$key]??'Not recorded') ?></dd><?php endforeach; ?><?php if($person['membership_id']): ?><dt class="col-sm-4">Party ID / Sys No.</dt><dd class="col-sm-8"><?= e(member_identifier($person)) ?></dd><?php endif; ?><?php if(\App\Security\ExecutiveAccess::contacts((int)$person['id'])): ?><?php foreach(['phone'=>'Phone','email'=>'Email','address'=>'Street address'] as $key=>$label): ?><dt class="col-sm-4"><?= e($label) ?></dt><dd class="col-sm-8"><?= e(\App\Crypto::decrypt($person[$key.'_encrypted'])?:'Not recorded') ?></dd><?php endforeach; ?><dt class="col-sm-4">Date of birth</dt><dd class="col-sm-8"><?= e($person['date_of_birth']?:'Not recorded') ?></dd><?php endif; ?></dl></div></div></section>
<?php if(\App\Security\ExecutiveAccess::canReview((int)$person['id'])): ?><section class="card card-body mt-4"><h2 class="h5">Flag a correction</h2><p>Describe the issue for an administrator or registrar. This does not change the person’s record. Do not include unnecessary sensitive details.</p><form action="<?= e(url()) ?>" method="post"><?= csrf() ?><input type="hidden" name="_action" value="executive_flag"><input type="hidden" name="voter_id" value="<?= (int)$person['id'] ?>"><label class="form-label" for="review-note">Issue to review</label><textarea class="form-control mb-3" id="review-note" name="note" maxlength="1000" rows="3" required></textarea><button class="btn btn-primary">Send for review</button></form></section><?php endif; ?>

